#include <algorithm>
#include <iostream>
#include <limits>
#include <vector>

using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<long long> a(n);
    for (long long& x : a) cin >> x;

    if (n < 3) {
        cout << 0;
        return 0;
    }

    vector<vector<long long>> dp(n, vector<long long>(n, 0));

    for (int length = 3; length <= n; ++length) {
        for (int left = 0; left + length <= n; ++left) {
            int right = left + length - 1;
            long long best = numeric_limits<long long>::lowest();

            for (int middle = left + 1; middle < right; ++middle) {
                best = max(best, dp[left][middle] + dp[middle][right]);
            }

            dp[left][right] = best + min(a[left], a[right]);
        }
    }

    long long answer = numeric_limits<long long>::lowest();
    for (int left = 0; left < n; ++left) {
        for (int right = left + 2; right < n; ++right) {
            answer = max(answer, dp[left][right]);
        }
    }

    cout << answer;
    return 0;
}

